class GeminiRequestError(RuntimeError):
    def __init__(
        self,
        message: str,
        *,
        status_code: int = 0,
        retryable: bool = False,
        invalid_key: bool = False,
    ) -> None:
        super().__init__(message)
        self.status_code = status_code
        self.retryable = retryable
        self.invalid_key = invalid_key

